parameters.jsCode:
// Extract booking data from Calendly webhook
const payload = $input.first().json.payload;
const event = payload.event;
const invitee = payload.invitee;

// Parse event time
const startTime = new Date(event.start_time);
const endTime = new Date(event.end_time);

// Extract property address from event name or questions
const propertyAddress = event.name.includes('Property Viewing:') 
  ? event.name.split('Property Viewing:')[1].trim()
  : 'Address TBD';

// Extract custom questions (lead name, phone, property interest)
const questions = invitee.questions_and_answers || [];
const leadPhone = questions.find(q => q.question.includes('phone'))?.answer || '';
const propertyInterest = questions.find(q => q.question.includes('property') || q.question.includes('address'))?.answer || propertyAddress;

return [{
  json: {
    bookingId: event.uri.split('/').pop(),
    leadName: invitee.name,
    leadEmail: invitee.email,
    leadPhone: leadPhone,
    propertyAddress: propertyInterest,
    viewingDate: startTime.toISOString().split('T')[0],
    viewingTime: startTime.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' }),
    startTime: startTime.toISOString(),
    endTime: endTime.toISOString(),
    calendarLink: event.calendar_link || '',
    rescheduleUrl: invitee.reschedule_url || '',
    cancelUrl: invitee.cancel_url || '',
    timezone: invitee.timezone || 'America/Chicago',
    confirmed: false,
    status: 'Scheduled'
  }
}];

