parameters.jsCode:
// Calculate which reminders to send (24hr or 2hr)
const events = $input.all();
const now = new Date();
const reminders = [];

for (const item of events) {
  const event = item.json;
  const startTime = new Date(event.start.dateTime);
  const hoursUntil = (startTime - now) / (1000 * 60 * 60);

  // Extract lead contact from event description
  const description = event.description || '';
  const emailMatch = description.match(/Lead Email:\s*([^\n]+)/);
  const phoneMatch = description.match(/Lead Phone:\s*([^\n]+)/);

  const leadEmail = emailMatch ? emailMatch[1].trim() : '';
  const leadPhone = phoneMatch ? phoneMatch[1].trim() : '';

  if (!leadEmail && !leadPhone) continue;

  // 24-hour reminder (between 22-26 hours before)
  if (hoursUntil >= 22 && hoursUntil <= 26) {
    reminders.push({
      json: {
        type: '24hr',
        eventId: event.id,
        summary: event.summary,
        startTime: event.start.dateTime,
        location: event.location,
        leadEmail,
        leadPhone,
        hoursUntil: Math.round(hoursUntil)
      }
    });
  }

  // 2-hour reminder (between 1.5-2.5 hours before)
  else if (hoursUntil >= 1.5 && hoursUntil <= 2.5) {
    reminders.push({
      json: {
        type: '2hr',
        eventId: event.id,
        summary: event.summary,
        startTime: event.start.dateTime,
        location: event.location,
        leadEmail,
        leadPhone,
        hoursUntil: Math.round(hoursUntil * 10) / 10
      }
    });
  }
}

return reminders.length > 0 ? reminders : [{ json: { noReminders: true } }];
